<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();api_rate_limit($user,'transactions.list',60,60);$page=max(1,min(100000,(int)($_GET['page']??1)));$stmt=db()->prepare('SELECT transaction_id,type,amount,previous_balance,new_balance,status,reference,description,created_at FROM wallet_transactions WHERE user_id=? ORDER BY id DESC LIMIT 20 OFFSET '.(($page-1)*20));$stmt->execute([$user['id']]);json_response(true,'Transactions retrieved',['items'=>$stmt->fetchAll(),'page'=>$page]);
